class Native:
    def __init__(self):
        torch.set_num_threads(1);self.config=read(B/'effective_config.json');self.args=OmegaConf.create(self.config)
        self.files=[B/f'{p}10000.pth' for p in ['chkpnt','dynamic_chkpnt','env_light_chkpnt','training_state']]
        self.before={str(p):(p.stat().st_size,p.stat().st_mtime_ns) for p in self.files}
        self.static=GaussianModel(self.args);self.dynamic=Dynamic_GaussianModel(self.args);self.env=EnvLight(resolution=self.args.env_map_res).cuda()
        for p,model in zip(self.files,[self.static,self.dynamic,self.env]):
            payload,step=torch.load(str(p),map_location='cpu',weights_only=False,mmap=True);assert step==10000;payload=list(payload)
            if 'env_light' in p.name:payload[0]=torch.nn.Parameter(payload[0].detach().cuda(),requires_grad=False)
            else:
                for i in range(1,11):payload[i]=payload[i].detach().cuda()
                model.time_duration=tuple(self.config['time_duration'])
            model.restore(tuple(payload),training_args=None)
            assert getattr(model,'optimizer',None) is None
            for v in vars(model).values():
                if torch.is_tensor(v):v.requires_grad_(False)
            del payload;gc.collect()

def install_identity_serialization():
    from scene.gaussian_model import GaussianModel, Dynamic_GaussianModel
    # Identical 18-field schema; base implementation adds/restores existing
    # sgcm_lineage_v1 metadata before loading plain Adam. No dynamic SGCM enabled.
    Dynamic_GaussianModel.capture = GaussianModel.capture
    Dynamic_GaussianModel.restore = GaussianModel.restore

def actor_ids(dynamic):
    ids = getattr(dynamic, '_sgcm_lineage_ids', None)
    if ids is None or ids.shape != (len(dynamic.get_xyz),):
        raise RuntimeError('Dynamic checkpoint lacks persistent per-source ownership')
    if bool(((ids < 0) | (ids >= STATIC_INITIAL_ROWS + A37_INITIAL_ROWS)).any()):
        raise RuntimeError('Unknown dynamic source ID')
    return torch.where(ids < STATIC_INITIAL_ROWS, 6, 37)

def get_features(self):
    features_dc = self._features_dc
    features_rest = self._features_rest
    return torch.cat((features_dc, features_rest), dim=1)

def _tensor_versions(self):
    versions = {}
    for name, model in (('static', self.n.static), ('dynamic', self.n.dynamic)):
        for key, value in vars(model).items():
            if torch.is_tensor(value):
                versions[(name, key)] = (id(value), value._version)
    for key, value in self.exp.repair.state_dict(keep_vars=True).items():
        versions[('repair', key)] = (id(value), value._version)
    for key, value in self.n.env.named_parameters():
        versions[('environment_parameter', key)] = (id(value), value._version)
    for key, value in self.n.env.named_buffers():
        versions[('environment_buffer', key)] = (id(value), value._version)
    return versions

def assert_unchanged(self):
    assert self.n.unchanged(), 'Native checkpoint files changed'
    assert self.n.before == self.parent_identity, 'Native baseline identity changed'
    assert self._tensor_versions() == self._versions, 'Frozen native/road tensors changed'
    assert (id(self.road_colors), self.road_colors._version) == self._road_color_version

def _road(self, camera, channels, precomputed):
    rows = road_kwargs(camera, self.exp.repair.road, self.pipe, channels,
                       precomputed_color=precomputed)
    if precomputed:
        rows['colors_precomp'] = self.road_colors
    else:
        rows['shs'] = rows['shs'].clone()
        rows['shs'][:, 0] = (self.road_colors-.5)/DC
    return tagged(rows, 'road')

def select_rows(rows, keep):
    return {key: None if value is None else value[keep].contiguous()
            for key, value in rows.items()}


def tagged(rows, group=None, owners=None):
    """24-feature ABI: depth, one, four group flags, then eighteen zeros."""
    source = rows['features']
    feature = source.new_zeros((len(source), 24))
    feature[:, :2] = source[:, :2]
    if owners is not None:
        feature[owners, 2] = 1
        feature[~owners, 3] = 1
    elif group is not None:
        feature[:, 2 + GROUPS.index(group)] = 1
    return dict(rows, features=feature)

def __init__(self, arrays, metadata=None):
    super().__init__()
    for names, dtype in ((FLOAT_FIELDS, torch.float32), (BOOL_FIELDS, torch.bool), (INT_FIELDS, torch.int64)):
        for key in names:
            self.register_buffer(key, torch.as_tensor(np.array(arrays[key], copy=True), dtype=dtype))
    count = len(self.xyz)
    if count <= 0 or self.xyz.shape != (count, 3) or self.normal.shape != (count, 3) or self.box.shape != (3,):
        raise ValueError('Invalid frozen asset geometry shapes')
    if not bool((self.box > 0).all()):
        raise ValueError('Frozen asset box dimensions must be positive')
    for key in GEOMETRY_FIELDS:
        value = getattr(self, key)
        if not bool(torch.isfinite(value).all()):
            raise ValueError('Nonfinite geometry: '+key)
        if key not in ('xyz', 'normal', 'box') and value.shape != (count,):
            raise ValueError('Wrong row count: '+key)
    if not bool((self.sigma > 0).all() and (self.thickness > 0).all() and
                ((self.opacity > 0) & (self.opacity < 1)).all()):
        raise ValueError('Invalid frozen scale/opacity')
    if not torch.allclose(self.normal.norm(dim=1), torch.ones(count), atol=2e-6, rtol=0):
        raise ValueError('Frozen normals must be unit length')
    self.geometry_hash = hash_geometry(self._geometry_arrays())
    expected = str(np.asarray(arrays.get('geometry_hash', self.geometry_hash)).item())
    if expected != self.geometry_hash:
        raise ValueError('Frozen geometry hash mismatch')
    reserved = set(GEOMETRY_FIELDS) | {'rgb', 'colour_inferred', 'geometry_hash', 'metadata_json',
                                     'canonical_sh', 'coefficients', 'sh', 'sh_degree', 'provenance_hash'}
    self._extra_names, self._extra_arrays = [], {}
    for key, value in arrays.items():
        if key in reserved:
            continue
        value = np.array(value, copy=True)
        if value.dtype.kind in 'biuf' and not hasattr(self, key):
            self.register_buffer(key, torch.as_tensor(value))
            self._extra_names.append(key)
        else:
            value.setflags(write=False)
            self._extra_arrays[key] = value
    self.provenance_hash = self._provenance_hash()
    if 'provenance_hash' in arrays and str(arrays['provenance_hash']) != self.provenance_hash:
        raise ValueError('Extra source/child provenance hash mismatch')
    self.metadata = deepcopy(metadata or {})
    initial = np.zeros((count, 16, 3), np.float32)
    rgb = np.asarray(arrays.get('rgb', np.full((count, 3), .5)), np.float32)
    if rgb.shape != (count, 3):
        raise ValueError('RGB seed must match geometry row count')
    initial[:, 0] = (rgb-.5)/C0
    supplied = arrays.get('canonical_sh', arrays.get('coefficients', arrays.get('sh', initial)))
    self.register_buffer('coefficients', torch.zeros((count, 16, 3), dtype=torch.float32))
    self.register_buffer('colour_inferred', torch.as_tensor(
        np.array(arrays.get('colour_inferred', np.ones(count, bool)), copy=True), dtype=torch.bool))
    if self.colour_inferred.shape != (count,):
        raise ValueError('Wrong inferred-color row count')
    self.set_coefficients(supplied)
    self._rotation_cache = {}
    self.last_diagnostics = None

@classmethod
def from_geometry(cls, path):
    with np.load(path, allow_pickle=False) as bank:
        arrays = {key: bank[key] for key in bank.files}
    metadata = json.loads(str(np.asarray(arrays.get('metadata_json', '{}')).item()))
    return cls(arrays, metadata)

@torch.no_grad()
def set_coefficients(self, values, colour_inferred=None):
    value = torch.as_tensor(values, dtype=self.coefficients.dtype, device=self.coefficients.device)
    if value.shape != self.coefficients.shape or not bool(torch.isfinite(value).all()):
        raise ValueError('Expected finite canonical SH coefficients [N,16,3]')
    self.coefficients.copy_(value)  # Deliberately no range constraint/projection.
    if colour_inferred is not None:
        flag = torch.as_tensor(colour_inferred, dtype=torch.bool, device=self.colour_inferred.device)
        if flag.shape != self.colour_inferred.shape:
            raise ValueError('Wrong inferred-color row count')
        self.colour_inferred.copy_(flag)

class Repair(torch.nn.Module):
    def __init__(self,ref,meta):
        super().__init__();self.road=StableRoad(ref,meta)
        with torch.no_grad():self.road.opacity.copy_(torch.logit(torch.as_tensor(ref['road_opacity'][self.road.ids,None],device='cuda').clamp(.00001,.99999)))
        self.road.requires_grad_(False)
        self.register_buffer('ids',torch.as_tensor(np.load(RUN/'inputs/contributors.npz')['ids'],device='cuda',dtype=torch.long))
        self.gate_raw=torch.nn.Parameter(torch.full((len(self.ids),),2.,device='cuda'))
r4.Repair=Repair

class Experiment(r4.Experiment):
    def __init__(self):super().__init__();self.settings=json.loads((RUN/'settings.json').read_text())
    def render(self,raw,enabled=True,camera=None,keep=False):
        c=camera or self.camera(raw)
        if not enabled:
            return self.n.render(c,dynamic=keep)
        return self.n.render(c,road=self.repair.road,ids=self.repair.ids,
                             gates=self.repair.gate_raw.sigmoid(),dynamic=keep)

def road_kwargs(camera, road, pipe, sh_channels=1, precomputed_color=False, for_training=False):
    xyz = road.xyz
    homogeneous = torch.cat((xyz, torch.ones_like(xyz[:, :1])), 1)
    depth = homogeneous @ camera.world_view_transform[:, 2:3]
    covariance = None
    if pipe.compute_cov3D_python:
        from utils.general_utils import build_scaling_rotation, strip_symmetric
        matrix = build_scaling_rotation(road.scaling, road.rotation)
        covariance = strip_symmetric(matrix @ matrix.transpose(1, 2))
    shs = None
    if not precomputed_color:
        rest = road.dc.new_zeros((len(xyz), sh_channels-1, 3))
        shs = torch.cat((road.dc, rest), 1)
    return dict(means3D=xyz, means2D=torch.zeros_like(xyz), shs=shs,
        colors_precomp=road.colors() if precomputed_color else None,
        features=torch.cat((depth, torch.ones_like(depth)), 1),
        opacities=road.opacity.sigmoid(), scales=None if covariance is not None else road.scaling,
        rotations=None if covariance is not None else road.rotation, cov3D_precomp=covariance,
        mask=road.active if for_training else road.output_mask())


def merge_rows(left, right):
    result = {}
    if set(left) != set(right):
        raise ValueError('光栅字段不匹配')
    for name in left:
        a, b = left[name], right[name]
        if a is None and b is None:
            result[name] = None
        elif a is None or b is None:
            raise ValueError('光栅表示不一致：'+name)
        else:
            result[name] = torch.cat((a, b), 0).contiguous()
    return result

def render_rows(self, raw, scene):
    data = self.raw(raw)
    if 'rows' in scene:
        rows, background, environment = scene['rows'], scene['bg'], scene['env']
    else:
        rows, background, environment = scene, self.n.bg, data['env']
    out = raster(data['cam'], self.pipe, self.n.static.active_sh_degree, rows, background)
    out['rgb_premultiplied'] = out['rgb']
    if environment is not None:
        out['rgb'] = out['rgb']+(1-out['alpha'])*environment
    out['component_alpha_T'] = out['extra'][:4]
    assert float((out['component_alpha_T'].sum(0)-out['alpha'][0]).detach().abs().max()) < 2e-5
    if 'meta' in scene:
        out['meta'] = scene['meta']
    return out

def render_scene(self, raw, asset=None, delete=False, baseline=False):
    return self.render_rows(raw, self.scene(raw, asset, delete=delete, baseline=baseline))
